#include "ux_support.h"
#include <QCoreApplication>
int main(int argc,char**argv){QCoreApplication app(argc,argv);if(argc!=2)return 64;try{std::filesystem::path data=argv[1];ux::Shell shell(data/"ui-stage/application",data/"ui-data");Canvas canvas(shell);CHECK(shell.choose(0));canvas.ready();until([&]{shell.tick();canvas.changes();return shell.semantics().ready()&&!shell.semantics().busy();}); /* D2: the page may show before its semantic data; it is painted on arrival */CHECK(shell.page()==0&&shell.semantics().highlights().size()==1);auto vocab=semantic::loadVocabulary(data/"ui-data");CHECK(vocab["records"].toArray().size()==1&&vocab["records"].toArray()[0].toObject()["normalized"].toString()=="reader");CHECK(shell.finish(2000));std::puts("SEMANTIC_FRESH_PROCESS_REOPEN_PASS highlight=1 vocabulary=1 page=0");return 0;}catch(const std::exception& e){std::fprintf(stderr,"SEMANTIC_REOPEN_FAIL %s\n",e.what());return 1;}}
